FLValue ufl_math_clamp(FLValue v, FLValue lo, FLValue hi) {
    double val = (v.tag == FL_INT) ? (double)v.i : v.f;
    double low = (lo.tag == FL_INT) ? (double)lo.i : lo.f;
    double high = (hi.tag == FL_INT) ? (double)hi.i : hi.f;
    if (val < low) val = low;
    if (val > high) val = high;
    return fl_float(val);
}
